  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED brought quantum optics into a solid-state device, enabling strong, controllable light–matter coupling and becoming a major platform for quantum experiments and computing. This is a foundational physics achievement beyond its technological promise.",
        "attribution": "Blais supplied central theoretical foundations, Wallraff helped establish the experimental regime, and Schoelkopf led key device and measurement work. The field grew through many groups, so the boundary of the prize contribution needs careful definition.",
        "maturity": "The platform has been reproduced and extended across laboratories for two decades, with increasingly sophisticated control and measurements.",
        "uncertainties": [
          "The discovery is collective, and selecting three people risks omitting important contributions, including Girvin's theoretical role."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected despite the fragility of quantum states. Its concepts underpin fault-tolerant quantum computing and have influenced quantum physics well beyond any one hardware platform.",
        "attribution": "Shor and Steane developed landmark error-correcting codes, while Kitaev introduced the topological perspective and influential fault-tolerant constructions. These are distinct, complementary contributions.",
        "maturity": "The theory is established, and experiments now demonstrate increasingly capable error correction. Large-scale fault-tolerant operation remains unachieved, but the underlying physics has had time to prove its significance.",
        "uncertainties": [
          "Whether the prize should recognize the theoretical framework now or await a decisive experimental demonstration of scalable fault tolerance."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made Hubbard-model physics experimentally accessible in a clean and controllable setting. The work opened a powerful route to studying quantum many-body phenomena.",
        "attribution": "Bloch and Greiner led landmark experimental demonstrations, while Zoller helped establish the theoretical vision for quantum simulation with trapped atoms. Cirac also made major contributions, making any three-person attribution difficult.",
        "maturity": "The platform and its core methods are well established, with extensive follow-up experiments and increasingly precise control. Some targeted problems, especially in regimes relevant to high-temperature superconductivity, remain unresolved.",
        "uncertainties": [
          "The scope of the credit depends on whether the prize recognizes the original platform, particular many-body results, or the broader quantum-simulation program."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade and programmable neutral-atom arrays created a flexible platform for controlled many-body physics and quantum information, with rapid experimental growth and clear demonstrations of new regimes.",
        "attribution": "Lukin's work helped establish the blockade concept, while Browaeys and Saffman led influential experimental programs that developed controllable arrays. The platform emerged through substantial contributions from several groups.",
        "maturity": "Blockade is well confirmed, and programmable arrays have produced increasingly capable and reproducible experiments. The field is still young relative to the duration over which its broad scientific impact can be judged.",
        "uncertainties": [
          "The long-term significance of the platform's discoveries remains unsettled, and early contributions to blockade and later array development are spread across researchers."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals and band gaps established ways to control the propagation and emission of light through engineered periodic structures. The concepts became foundational in photonics and joined materials physics with optical design.",
        "attribution": "Yablonovitch and John independently articulated central ideas, while Joannopoulos developed theory and helped shape the field. The near-simultaneous origins make a three-person division defensible but not unique.",
        "maturity": "The basic physics has been experimentally confirmed and widely developed over decades. The field has a durable scientific and technological footprint.",
        "uncertainties": [
          "The prize would need to define whether it honors the original band-gap proposals, the experimental realization, or the broader consequences."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B034",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks enabled extraordinary frequency precision while controlling atomic motion, advancing tests of fundamental physics and precision measurement. This is a strong physics achievement as well as a potential timekeeping technology.",
        "attribution": "Katori and Ye developed leading, complementary approaches and drove the field's experimental progress. The two-person attribution is unusually clear for a major precision-measurement advance.",
        "maturity": "The clocks have undergone extensive refinement and independent development, with accuracy sufficient for demanding physical applications. Their scientific reach is still expanding.",
        "uncertainties": [
          "It is not yet clear which foundational clock advances should define the prize contribution amid continued improvement by many groups."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Daniel Loss",
        "David P. DiVincenzo",
        "Lieven M. K. Vandersypen"
      ],
      "assessment": {
        "nobel_worthiness": "Electron spin qubits in quantum dots connected a compelling theoretical proposal to an experimentally viable solid-state system. This approach has become an important route to quantum control and computation.",
        "attribution": "Loss and DiVincenzo formulated the influential spin-qubit proposal and criteria, while Vandersypen helped establish and advance experimental control. Later progress depends on many groups and device innovations.",
        "maturity": "The field has shown substantial progress in coherent control and multi-qubit operations, but scaling, device variability, and reliable error correction remain active challenges.",
        "uncertainties": [
          "The platform's eventual role in fault-tolerant computing is not settled, and the prize contribution could be framed around either the proposal or later experimental milestones."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Charles L. Kane",
        "Laurens W. Molenkamp",
        "Qi-Kun Xue"
      ],
      "assessment": {
        "nobel_worthiness": "Topological insulators and quantized edge transport opened a major direction in condensed-matter physics, linking topology to experimentally accessible electronic states and inspiring extensive research.",
        "attribution": "Kane made foundational theoretical contributions to the quantum spin Hall effect, while Molenkamp and Xue led important experimental realizations of quantized edge transport and the quantum anomalous Hall effect. These are related but distinct lines of work.",
        "maturity": "The central phenomena have been demonstrated and the field has developed over many years. The most consequential applications and extensions, including robust topological devices, remain active research goals.",
        "uncertainties": [
          "The ballot combines multiple effects with different histories, so its scope may be too broad for a single, sharply attributed prize."
        ]
      }
    }
  ]
}
